const digitized = {
  "2023": [
    {n:20,skill:"Pattern",title:"Triangles made with sticks",en:"Sticks were used to form triangles. Figure 1 uses 3 sticks, Figure 2 uses 5, Figure 3 uses 7 and Figure 4 uses 9. How many sticks are needed for Figure 9?",vi:"Các que được xếp thành dãy tam giác. Hình 1 có 3 que, sau đó mỗi hình thêm 2 que. Hỏi Hình 9 cần bao nhiêu que?",answer:"19",unit:"sticks",hint:"There are 8 steps from Figure 1 to Figure 9. Two sticks are added at each step.",steps:["Number of steps:","9 - 1 = 8","Number of new sticks:","8 × 2 = 16 sticks","Number of sticks in Figure 9:","3 + 16 = 19 sticks"],image:"assets/fig-2023-20.jpg"},
    {n:21,skill:"Money and mass",title:"Selling mangoes",en:"Mangoes were sold at $24 for 3 kg. Mdm Ong sold 27 kg of mangoes. How much did she receive?",vi:"3 kg xoài bán được 24 đô-la. Bà Ong bán 27 kg. Hỏi bà nhận được bao nhiêu tiền?",answer:"216",unit:"$",hint:"Find the price of 1 kg first, then multiply it by 27.",steps:["Cost of 1 kg of mangoes:","$24 ÷ 3 = $8","Money received for 27 kg:","$8 × 27 = $216"]},
    {n:24,skill:"Comparison",title:"A wallet and pouches",en:"A wallet and 4 pouches cost $265. The wallet and 2 such pouches cost $189. Find the cost of 1 wallet.",vi:"Một chiếc ví và 4 túi nhỏ giá 265 đô-la. Chiếc ví đó và 2 túi nhỏ giá 189 đô-la. Tìm giá chiếc ví.",answer:"113",unit:"$",hint:"Subtract the two totals. The difference is the cost of 2 pouches.",steps:["Cost of 2 pouches:","$265 - $189 = $76","Cost of 1 pouch:","$76 ÷ 2 = $38","Cost of the wallet:","$189 - $38 × 2 = $113"]},
    {n:27,skill:"Part-whole model",title:"Jack and Tom's money",en:"Jack and Tom had $330 altogether. Jack gave $87 to Tom. In the end, Tom had twice as much as Jack. How much did Tom have at first?",vi:"Jack và Tom có tất cả 330 đô-la. Jack đưa Tom 87 đô-la. Cuối cùng Tom có số tiền gấp đôi Jack. Hỏi lúc đầu Tom có bao nhiêu tiền?",answer:"133",unit:"$",hint:"The total is still $330 after the transfer. Split it into 3 equal parts.",steps:["The total stayed at $330.","Jack had 1 part and Tom had 2 parts.","Value of 1 part:","$330 ÷ 3 = $110","Tom had after receiving the money:","$110 × 2 = $220","Tom had at first:","$220 - $87 = $133"]}
  ],
  "2024": [
    {n:2,skill:"Multiples",title:"Numbers divisible by 8",en:"How many numbers between 30 and 60 can be divided exactly by 8?",vi:"Có bao nhiêu số nằm giữa 30 và 60 chia hết cho 8?",answer:"4",unit:"numbers",hint:"List the multiples of 8 after 30 and stop before 60.",steps:["The numbers are:","32, 40, 48, 56","There are 4 numbers."]},
    {n:3,skill:"Multiplication",title:"Find the missing number",en:"9 + 9 + 9 + 9 = 6 × □. What is the missing number?",vi:"Tìm số còn thiếu trong phép tính: 9 + 9 + 9 + 9 = 6 × □.",answer:"6",unit:"",hint:"Find the total on the left first.",steps:["9 + 9 + 9 + 9 = 36","The missing number is:","36 ÷ 6 = 6"]},
    {n:6,skill:"Time",title:"25 minutes earlier",en:"What is 25 minutes before the time shown on the clock?",vi:"Đồng hồ chỉ 15 giờ 55 phút. Thời điểm trước đó 25 phút là mấy giờ?",answer:"15:30",accepted:["15:30","3:30","1530","330"],unit:"",hint:"Go back 20 minutes, then 5 more minutes.",steps:["The clock shows 15:55.","20 minutes earlier is 15:35.","5 more minutes earlier is 15:30.","So the time was 15:30."],image:"assets/fig-2024-06.jpg"},
    {n:8,skill:"Money",title:"How much money does Andy have?",en:"Andy has 3 fifty-dollar notes, 7 five-dollar notes and 6 twenty-cent coins. How much money does Andy have?",vi:"Andy có 3 tờ 50 đô-la, 7 tờ 5 đô-la và 6 đồng 20 xu. Andy có tất cả bao nhiêu tiền?",answer:"186.20",accepted:["186.2","186.20","$186.20"],unit:"$",hint:"Find the value of each group of notes and coins, then add them.",steps:["Value of the $50 notes:","3 × $50 = $150","Value of the $5 notes:","7 × $5 = $35","Value of the coins:","6 × $0.20 = $1.20","Total amount:","$150 + $35 + $1.20 = $186.20"],image:"assets/fig-2024-08.jpg"}
  ],
  "2026": [
    {n:41,skill:"Part-whole model",title:"Three colours of pens",en:"A shopkeeper has 622 pens. There are 4 times as many blue pens as green pens. There are 35 fewer red pens than blue pens. How many blue and red pens are there altogether?",vi:"Cửa hàng có 622 bút. Bút xanh gấp 4 lần bút lục. Bút đỏ ít hơn bút xanh 35 chiếc. Hỏi có tất cả bao nhiêu bút xanh và đỏ?",answer:"549",unit:"pens",hint:"Add 35 red pens for a moment. Then the total can be split into 9 equal parts.",steps:["If 35 red pens are added:","622 + 35 = 657 pens","Green = 1 part, blue = 4 parts, red = 4 parts.","Total number of parts:","1 + 4 + 4 = 9 parts","Value of 1 part:","657 ÷ 9 = 73 pens","Number of blue pens:","73 × 4 = 292 pens","Number of red pens:","292 - 35 = 257 pens","Blue and red pens altogether:","292 + 257 = 549 pens"]},
    {n:42,skill:"Supposition",title:"Small and big taxis",en:"11 taxis carried 52 passengers. Each small taxi carried 4 passengers and each big taxi carried 6. How many small taxis were hired?",vi:"11 xe taxi chở 52 người. Taxi nhỏ chở 4 người, taxi lớn chở 6 người. Có bao nhiêu taxi nhỏ?",answer:"7",unit:"taxis",hint:"Suppose all 11 taxis were big. Compare that number of passengers with 52.",steps:["Suppose all 11 taxis were big.","They would carry:","11 × 6 = 66 passengers","Extra passengers:","66 - 52 = 14 passengers","Changing one big taxi to a small taxi reduces 2 passengers.","Number of small taxis:","14 ÷ 2 = 7 taxis"]},
    {n:43,skill:"Length",title:"Six dustbins in a row",en:"6 dustbins, each 35 cm long, are in a row with equal gaps. The total length from the first to the last is 835 cm. Find one gap.",vi:"6 thùng rác, mỗi thùng dài 35 cm, xếp thành hàng với các khoảng cách bằng nhau. Tổng chiều dài là 835 cm. Tìm khoảng cách giữa hai thùng cạnh nhau.",answer:"125",unit:"cm",hint:"Six dustbins make 5 gaps. Subtract the total length of the dustbins first.",steps:["Total length of 6 dustbins:","35 × 6 = 210 cm","Total length of all gaps:","835 - 210 = 625 cm","There are 5 gaps between 6 dustbins.","Length of each gap:","625 ÷ 5 = 125 cm"],image:"assets/fig-2026-43.jpg"},
    {n:44,skill:"Grouping",title:"Lollipops at a party",en:"There were twice as many girls as boys. Each girl got 2 lollipops and each boy got 3. Mrs Tan gave out 154 lollipops. How many children were invited?",vi:"Số bé gái gấp đôi số bé trai. Mỗi bé gái nhận 2 kẹo, mỗi bé trai nhận 3 kẹo. Có 154 kẹo được phát. Hỏi có bao nhiêu bạn nhỏ?",answer:"66",unit:"children",hint:"Group 1 boy with 2 girls.",steps:["Make a group of 1 boy and 2 girls.","Lollipops for one group:","3 + 2 × 2 = 7 lollipops","Number of groups:","154 ÷ 7 = 22 groups","Each group has 3 children.","Number of children:","22 × 3 = 66 children"]}
  ]
};

const totals={"2023":45,"2024":31,"2026":45};
const papers=Object.fromEntries(Object.entries(totals).map(([year,total])=>{
  const ready=new Map(digitized[year].map(q=>[q.n,{...q,ready:true}]));
  return [year,Array.from({length:total},(_,i)=>ready.get(i+1)||{n:i+1,ready:false,skill:"In progress",title:`Question ${i+1}`,en:"This question is being digitised from the original paper. Its diagram, answer and child-friendly working will be added here.",vi:"Câu hỏi này đang được số hóa từ đề gốc."})];
}));

let currentYear="2023",currentIndex=papers["2023"].findIndex(q=>q.ready),translationOpen=false;
const saved=JSON.parse(localStorage.getItem("smc-progress-v2")||"{}");
const $=id=>document.getElementById(id);
const els={sourceLabel:$("sourceLabel"),skillLabel:$("skillLabel"),progressText:$("progressText"),progressBar:$("progressBar"),questionNumber:$("questionNumber"),questionTitle:$("questionTitle"),questionEnglish:$("questionEnglish"),questionVietnamese:$("questionVietnamese"),translateButton:$("translateButton"),sourceFigure:$("sourceFigure"),questionImage:$("questionImage"),answerInput:$("answerInput"),answerUnit:$("answerUnit"),feedback:$("feedback"),hintBox:$("hintBox"),hintText:$("hintText"),solutionSheet:$("solutionSheet"),studentWork:$("studentWork"),finalAnswer:$("finalAnswer"),questionMap:$("questionMap"),answeredCount:$("answeredCount"),prevButton:$("prevButton"),nextButton:$("nextButton")};

function key(q){return `${currentYear}-${q.n}`}
function record(q){return saved[key(q)]||{answer:"",checked:false,correct:false}}
function persist(q,patch){saved[key(q)]={...record(q),...patch};localStorage.setItem("smc-progress-v2",JSON.stringify(saved))}
function normalize(v){return v.trim().toLowerCase().replace(/\s+/g,"").replace(",",".")}
function updateCount(){const list=papers[currentYear],done=list.filter(q=>record(q).checked).length;els.answeredCount.textContent=`${done} / ${list.length} done`}
function renderMap(){
  els.questionMap.innerHTML="";
  papers[currentYear].forEach((q,i)=>{const state=record(q),b=document.createElement("button");b.className=`q-dot${i===currentIndex?" active":""}${state.checked?" done":""}${!q.ready?" pending":""}`;b.textContent=q.n;b.type="button";b.setAttribute("aria-label",`Open question ${q.n}${state.checked?", done":""}`);b.onclick=()=>{currentIndex=i;translationOpen=false;render()};els.questionMap.appendChild(b)});
  updateCount();
}
function render(){
  const list=papers[currentYear],q=list[currentIndex],state=record(q);
  els.sourceLabel.textContent=`SMC ${currentYear} · Question ${q.n}`;els.skillLabel.textContent=q.skill;els.progressText.textContent=`${q.n} / ${list.length}`;els.progressBar.style.width=`${q.n/list.length*100}%`;
  els.questionNumber.textContent=q.n;els.questionTitle.textContent=q.title;els.questionEnglish.textContent=q.en;els.questionVietnamese.textContent=q.vi||"";els.questionVietnamese.classList.toggle("hidden",!translationOpen);els.translateButton.textContent=translationOpen?"Hide translation":"Translate";els.translateButton.disabled=!q.vi;
  els.answerUnit.textContent=q.unit||"";els.answerInput.value=state.answer||"";els.answerInput.disabled=!q.ready;$("checkButton").disabled=!q.ready;$("hintButton").disabled=!q.ready;$("solutionButton").disabled=!q.ready;els.feedback.textContent=state.checked?(state.correct?"Correct!":"Not quite. Try again or use the hint."):"";els.feedback.className=`feedback${state.checked?(state.correct?" good":" bad"):""}`;
  els.hintBox.classList.add("hidden");els.solutionSheet.classList.add("hidden");$("solutionButton").textContent="Show solution";els.hintText.textContent=q.hint||"";els.studentWork.innerHTML=(q.steps||[]).map(s=>`<p>${s}</p>`).join("");els.finalAnswer.textContent=q.ready?`${q.answer}${q.unit?" "+q.unit:""}`:"";
  if(q.image){els.questionImage.src=q.image;els.questionImage.alt=`Diagram for question ${q.n}`;els.sourceFigure.classList.remove("hidden")}else{els.sourceFigure.classList.add("hidden");els.questionImage.removeAttribute("src")}
  els.prevButton.disabled=currentIndex===0;els.nextButton.textContent=currentIndex===list.length-1?"Back to Question 1 ↺":"Next →";renderMap();
}
function checkAnswer(){
  const q=papers[currentYear][currentIndex];if(!q.ready)return;const value=normalize(els.answerInput.value),accepted=(q.accepted||[q.answer]).map(normalize);
  if(!value){els.feedback.textContent="Please enter an answer first.";els.feedback.className="feedback bad";return}
  const correct=accepted.includes(value);persist(q,{answer:els.answerInput.value,checked:true,correct});els.feedback.textContent=correct?"Correct! Great work.":"Not quite. Try again or use the hint.";els.feedback.className=`feedback ${correct?"good":"bad"}`;renderMap();
}
document.querySelectorAll(".year-tab").forEach(tab=>tab.addEventListener("click",()=>{document.querySelectorAll(".year-tab").forEach(t=>{t.classList.toggle("active",t===tab);t.setAttribute("aria-selected",t===tab?"true":"false")});currentYear=tab.dataset.year;currentIndex=papers[currentYear].findIndex(q=>q.ready);translationOpen=false;render()}));
els.translateButton.onclick=()=>{translationOpen=!translationOpen;els.questionVietnamese.classList.toggle("hidden",!translationOpen);els.translateButton.textContent=translationOpen?"Hide translation":"Translate"};
$("checkButton").onclick=checkAnswer;els.answerInput.addEventListener("input",()=>persist(papers[currentYear][currentIndex],{answer:els.answerInput.value,checked:false,correct:false}));els.answerInput.addEventListener("keydown",e=>{if(e.key==="Enter")checkAnswer()});
$("hintButton").onclick=()=>els.hintBox.classList.toggle("hidden");$("solutionButton").onclick=()=>{els.solutionSheet.classList.toggle("hidden");$("solutionButton").textContent=els.solutionSheet.classList.contains("hidden")?"Show solution":"Hide solution"};
els.prevButton.onclick=()=>{if(currentIndex>0){currentIndex--;translationOpen=false;render()}};els.nextButton.onclick=()=>{currentIndex=(currentIndex+1)%papers[currentYear].length;translationOpen=false;render()};

let seconds=90*60,timerId=null;function updateTimer(){const m=Math.floor(seconds/60),s=seconds%60;$("timerText").textContent=`${String(m).padStart(2,"0")}:${String(s).padStart(2,"0")}`;if(seconds===0){clearInterval(timerId);timerId=null;$("timerState").textContent="Time's up"}}
$("timerButton").onclick=()=>{if(timerId){clearInterval(timerId);timerId=null;$("timerState").textContent="Resume"}else{if(seconds===0)seconds=90*60;timerId=setInterval(()=>{seconds--;updateTimer()},1000);$("timerState").textContent="Pause"}};
render();
